/* Simulado 4 — PP-PE (Cebraspe) — o[0] = correta, o[1] = pegadinha principal; fixa:true mantém a ordem (c = correta, pi = pegadinha) */
window.SIMULADOS = window.SIMULADOS || [];
var ITENS4 = ["Apenas o item I está certo.","Apenas o item II está certo.","Apenas os itens I e II estão certos.","Apenas os itens II e III estão certos.","Todos os itens estão certos."];
window.SIMULADOS.push({
id: 4,
titulo: "Simulado 4",
tema: "Nível avançado",
descricao: "Itens I, II e III, jurisprudência e mudanças legislativas recentes: o nível mais alto da banca.",
textos: {
t1: {
titulo: "Texto 1",
corpo: [
"No Brasil, uma parcela expressiva das pessoas privadas de liberdade ainda aguarda julgamento. São homens e mulheres que, do ponto de vista jurídico, permanecem inocentes, mas que vivem a rotina do cárcere como se condenados fossem: dividem celas, horários e restrições com quem já cumpre pena, muitas vezes por meses ou anos.",
"A prisão provisória não é, em si, uma anomalia. Há situações em que ela se mostra indispensável para proteger a investigação, a vítima ou a própria sociedade. O problema surge quando a exceção se converte em hábito e a cautela passa a funcionar como antecipação de pena. Nesse cenário, a presunção de inocência, princípio que a Constituição consagra, transforma-se em fórmula vazia.",
"As audiências de custódia, implantadas em todo o país na última década, representaram um avanço importante. Ao colocar o preso diante de um juiz em até vinte e quatro horas, permitiram identificar prisões desnecessárias e coibir abusos no momento da detenção. Ainda assim, seus efeitos dependem da qualidade das decisões tomadas nelas e da existência de alternativas concretas à prisão.",
"Para quem trabalha nas unidades, o excesso de presos provisórios tem consequências palpáveis. A rotatividade dificulta a classificação adequada, a separação entre perfis distintos torna-se quase impossível e as galerias, já superlotadas, recebem diariamente pessoas cuja situação processual é incerta. Não raro, é nesse ambiente que facções criminosas encontram seus novos integrantes.",
"Enfrentar o problema exige mais do que construir vagas. Exige celeridade processual, uso responsável das medidas cautelares e investimento em monitoração eletrônica, quando cabível. Exige, sobretudo, que se leve a sério a ideia de que prender antes do julgamento deve ser sempre a última alternativa — e nunca a primeira."
],
fonte: "Texto inédito, elaborado para este simulado."
}
},
discursiva: {
tema: "Mulheres privadas de liberdade e especificidades de gênero",
comando: "O número de mulheres presas no Brasil cresceu de forma acelerada nas últimas décadas, em grande parte por crimes relacionados ao tráfico de drogas. Normas nacionais e internacionais, como a LEP, a PNAMPE (Portaria Interministerial MJ/SPM nº 210/2014) e as Regras de Bangkok, reconhecem necessidades específicas dessa população. Considerando esse contexto, redija um texto dissertativo acerca do tema a seguir.",
topicos: [
"Aponte duas especificidades da mulher privada de liberdade que exigem tratamento diferenciado pelo sistema prisional.",
"Discorra sobre as garantias relativas à maternidade previstas na legislação brasileira (gestação, parto, amamentação e convivência com os filhos).",
"Analise o papel do policial penal na efetivação desses direitos sem prejuízo da segurança da unidade."
],
espelho: [
"Especificidades: saúde da mulher (ginecológica, pré-natal), maternidade, maior abandono familiar, histórico de violência de gênero, necessidade de revista e custódia por servidoras, perfil de baixa periculosidade em muitos casos.",
"Maternidade: pré-natal e pós-parto (LEP, art. 14, § 3º); berçário mínimo até 6 meses (art. 83, § 2º); creche de 6 meses a 7 anos (art. 89); vedação de algemas no parto e no puerpério imediato (CPP, art. 292, parágrafo único); prisão domiciliar no lugar da preventiva para gestantes e mães (CPP, arts. 318 e 318-A; HC 143.641); progressão especial com 1/8 (LEP, art. 112, § 3º).",
"PNAMPE e Regras de Bangkok: prevenção da violência, adequação de normas às especificidades de gênero, humanização, alternativas à prisão.",
"Papel do policial penal: segurança interna das alas femininas por servidoras (LEP, art. 83, § 3º), escolta humanizada, observância de protocolos, comunicação de demandas de saúde, respeito à dignidade.",
"Texto dissertativo-argumentativo, em registro formal, coeso, até 30 linhas."
]
},
q: [
/* ===================== P1 ===================== */
{d:"LP",a:"Compreensão e interpretação",t:"t1",
e:"De acordo com o texto 1, a prisão provisória",
o:["é legítima em determinadas situações, mas torna-se problemática quando passa a funcionar como antecipação de pena.",
"é uma anomalia incompatível, em qualquer caso, com a presunção de inocência.",
"deve ser abolida, pois as audiências de custódia a tornaram desnecessária.",
"é a principal causa da existência de facções criminosas no país.",
"atinge apenas pessoas que já foram condenadas em primeira instância."],
x:"O 2º parágrafo afirma que a prisão provisória “não é, em si, uma anomalia” e que pode ser indispensável; o problema é a exceção virar hábito e a cautela funcionar como antecipação de pena.",
p:["LIT","O texto diz exatamente o contrário: “A prisão provisória não é, em si, uma anomalia.” A banca retira o “não” e acrescenta “em qualquer caso”."]},

{d:"LP",a:"Inferência",t:"t1",
e:"Infere-se do 4º parágrafo do texto 1 que",
o:["o ambiente gerado pelo excesso de presos provisórios favorece o recrutamento de novos integrantes por facções criminosas.",
"as facções criminosas são as responsáveis pela superlotação das galerias.",
"a classificação adequada dos presos é impossível em qualquer unidade prisional.",
"os presos provisórios ingressam nas unidades já vinculados a facções.",
"a rotatividade de presos facilita a separação entre perfis distintos."],
x:"O parágrafo relaciona o excesso de provisórios à rotatividade, à falta de separação e à superlotação e conclui que “é nesse ambiente que facções criminosas encontram seus novos integrantes”.",
p:["INV","O texto aponta o ambiente superlotado como condição para o recrutamento. A opção inverte a relação de causa e efeito."]},

{d:"LP",a:"Concordância nominal",
e:"Assinale a opção em que a concordância nominal está de acordo com a norma-padrão.",
o:["É necessário paciência no atendimento às famílias.",
"Seguem anexo os relatórios solicitados pela direção.",
"As policiais mesmo conduziram a revista das visitantes.",
"A equipe chegou à unidade ao meio-dia e meio.",
"As servidoras ficaram meias preocupadas com a escala."],
x:"Com substantivo sem determinante, a expressão “é necessário” fica invariável (“É necessário paciência”; mas “É necessária a paciência”). “Anexo” concorda com o substantivo (“seguem anexos os relatórios”); “mesmo” com valor de “próprio” concorda (“as policiais mesmas”); “meio-dia e meia” (hora); “meio” advérbio é invariável (“meio preocupadas”).",
p:["GRAM","“Anexo” parece invariável como “em anexo”, mas, sem a preposição, é adjetivo e concorda: “seguem anexos os relatórios”."]},

{d:"LP",a:"Regência verbal",
e:"Assinale a opção em que a regência verbal está de acordo com a norma-padrão.",
o:["O policial penal assistiu ao depoimento do preso na audiência.",
"Os servidores preferem mais o turno diurno do que o noturno.",
"O diretor informou aos servidores de que a escala mudaria.",
"Todos devem obedecer as normas de segurança da unidade.",
"O visitante esqueceu-se o documento de identificação."],
x:"“Assistir”, no sentido de ver/presenciar, é transitivo indireto (assistir a). “Preferir” rege “a” e não admite “mais... do que”. “Informar” não admite dois objetos indiretos (informou aos servidores que...). “Obedecer” exige “a” (obedecer às normas). “Esquecer-se” pronominal exige “de” (esqueceu-se do documento).",
p:["GRAM","“Preferir mais... do que” é comum na fala, mas a norma-padrão exige “preferir uma coisa a outra”."]},

{d:"LP",a:"Coesão: referenciação",t:"t1",
e:"No 2º parágrafo do texto 1, a expressão “Nesse cenário” refere-se",
o:["à situação em que a exceção se converte em hábito e a cautela passa a funcionar como antecipação de pena.",
"às situações em que a prisão provisória se mostra indispensável para proteger a investigação.",
"à rotina do cárcere descrita no 1º parágrafo.",
"à implantação das audiências de custódia.",
"à proteção da vítima e da sociedade."],
x:"A expressão anafórica retoma o período imediatamente anterior: quando a exceção vira hábito e a cautela antecipa a pena, a presunção de inocência “transforma-se em fórmula vazia”.",
p:["REF","As situações de prisão indispensável também estão no parágrafo, mas nelas a presunção de inocência não se esvazia. O sentido mostra o referente correto."]},

{d:"LP",a:"Reescritura: conectores",t:"t1",
e:"No 3º parágrafo do texto 1, a expressão “Ainda assim” poderia ser substituída, sem prejuízo do sentido e da correção gramatical, por",
o:["Mesmo assim.",
"Por isso.",
"Assim sendo.",
"Desse modo.",
"Por conseguinte."],
x:"“Ainda assim” introduz ideia contrária à expectativa criada pelo que se disse antes (valor concessivo/adversativo), como “mesmo assim”, “apesar disso”, “contudo”. As demais expressões têm valor conclusivo.",
p:["VIZ","“Assim sendo” e “desse modo” compartilham a palavra “assim”, mas indicam conclusão, e não oposição."]},

{d:"LP",a:"Período composto: subordinação",t:"t1",
e:"No trecho “as galerias [...] recebem diariamente pessoas cuja situação processual é incerta” (4º parágrafo do texto 1), a oração “cuja situação processual é incerta”",
o:["é subordinada adjetiva restritiva, e o pronome “cuja” estabelece relação de posse entre “pessoas” e “situação processual”.",
"é subordinada adjetiva explicativa, motivo pelo qual poderia ser isolada por vírgulas sem alteração de sentido.",
"é subordinada substantiva objetiva direta do verbo “recebem”.",
"é coordenada sindética explicativa.",
"é subordinada adverbial causal."],
x:"A oração introduzida por “cuja” qualifica e delimita o substantivo “pessoas” (as pessoas cuja situação é incerta), sem vírgulas: é adjetiva restritiva. “Cujo/cuja” indica posse e concorda com o termo possuído (“situação”).",
p:["VIZ","Adjetivas explicativas vêm entre vírgulas e generalizam; as restritivas delimitam o sentido do antecedente. Colocar vírgulas aqui mudaria o sentido."]},

{d:"ETI",a:"Ética, moral e valores",
e:"Considere as afirmações a seguir.\n\nI A moral tem caráter prático e relaciona-se aos costumes e às normas de conduta vigentes em determinado grupo social.\nII A ética, como reflexão crítica, pode questionar as normas morais vigentes em uma sociedade.\nIII A conduta ética do servidor público dispensa a observância das normas legais quando estas contrariarem sua convicção pessoal.\n\nAssinale a opção correta.",
o:ITENS4, fixa:true, c:2, pi:4,
x:"I e II estão certos: a moral é prática e histórica; a ética é reflexão teórica e crítica, capaz de questionar a moral. III está errado: a convicção pessoal não autoriza o servidor a descumprir a lei; a ética pública pressupõe a legalidade (e a moralidade administrativa a complementa, não a substitui).",
p:["SENSO","O item III soa nobre (“seguir a consciência”), mas o servidor está vinculado à legalidade. Quem marca “todos certos” cai nele."]},

{d:"ETI",a:"Lei 8.112/1990: denúncia anônima",
e:"A corregedoria de um órgão federal recebeu denúncia anônima, acompanhada de fotografias, sobre desvio de materiais por servidor. Após apuração preliminar que confirmou indícios do fato, foi instaurado processo administrativo disciplinar. Segundo a jurisprudência do STJ, essa instauração é",
o:["válida, pois é permitida a instauração de PAD com base em denúncia anônima, desde que devidamente motivada e com amparo em investigação ou sindicância prévia.",
"nula, pois a Lei nº 8.112/1990 veda, em qualquer hipótese, a apuração de denúncias anônimas.",
"válida, pois a denúncia anônima basta, por si só, para instaurar o PAD e afastar o servidor.",
"nula, pois a instauração depende de prévia autorização judicial.",
"válida apenas se o denunciante for identificado até o fim da instrução."],
x:"Súmula 611 do STJ: desde que devidamente motivada e com amparo em investigação ou sindicância, é permitida a instauração de PAD com base em denúncia anônima, em face do poder-dever de autotutela. O art. 144 da Lei 8.112/1990 trata da denúncia identificada, mas não impede a apuração de ofício.",
p:["ABS","O art. 144 exige identificação do denunciante, o que leva o candidato a concluir que a denúncia anônima é proibida “em qualquer hipótese”. O STJ admite, com apuração prévia."]},

{d:"ETI",a:"Responsabilidade do servidor: independência das instâncias",
e:"Um servidor respondeu, pelo mesmo fato, a ação penal e a processo administrativo disciplinar. Nos termos da Lei nº 8.112/1990, sua responsabilidade administrativa será afastada no caso de",
o:["absolvição criminal que negue a existência do fato ou a sua autoria.",
"absolvição criminal por insuficiência de provas.",
"extinção da punibilidade pela prescrição penal.",
"arquivamento do inquérito policial por falta de justa causa.",
"absolvição criminal por qualquer fundamento."],
x:"Art. 126 da Lei 8.112/1990: a responsabilidade administrativa é afastada no caso de absolvição criminal que negue a existência do fato ou sua autoria. As sanções civis, penais e administrativas são independentes (art. 125). Absolvição por falta de provas não vincula a administração.",
p:["ALC","Absolvição por insuficiência de provas não afirma que o fato não ocorreu. Só a negativa do fato ou da autoria repercute na esfera administrativa."]},

{d:"ETI",a:"Impedimento e suspeição (Lei 9.784/1999)",
e:"O servidor designado para conduzir processo administrativo de interesse de um policial penal é amigo íntimo deste. Conforme a Lei nº 9.784/1999, essa situação configura",
o:["suspeição, que pode ser arguida pelo interessado.",
"impedimento, que gera nulidade absoluta e deve ser obrigatoriamente comunicado.",
"incompatibilidade funcional, que exige a exoneração do servidor.",
"conflito de competência, resolvido pela autoridade superior.",
"situação irrelevante, pois a amizade não afeta a imparcialidade presumida do servidor."],
x:"Art. 20 da Lei 9.784/1999: pode ser arguida a suspeição de quem tenha amizade íntima ou inimizade notória com algum dos interessados ou com seus cônjuges, parentes e afins até o 3º grau. O impedimento (art. 18) decorre de interesse direto, participação anterior como perito, testemunha ou representante, ou litígio com o interessado.",
p:["VIZ","Amizade íntima e inimizade notória são hipóteses de suspeição. Interesse direto, atuação anterior e litígio são de impedimento."]},

{d:"LEG",a:"EC estadual 53/2020",
e:"A Emenda Constitucional estadual nº 53/2020, ao alterar a Constituição do Estado de Pernambuco,",
o:["incluiu a Polícia Penal entre os órgãos de segurança pública e remeteu à lei a definição da manutenção da ordem, da segurança interna, da organização e do funcionamento da Polícia Penal.",
"definiu, ela própria, de forma detalhada, todas as atribuições do policial penal, dispensando lei complementar.",
"transferiu a Polícia Penal para a estrutura da Secretaria de Defesa Social.",
"extinguiu o cargo de agente de segurança penitenciária sem aproveitamento de seus ocupantes.",
"atribuiu à Polícia Penal a polícia judiciária das infrações cometidas nos estabelecimentos penais."],
x:"A EC 53/2020 alterou os arts. 101, 102 e 104: incluiu a Polícia Penal no rol do art. 101 (inciso IV), vinculou-a ao órgão administrador do sistema penal, previu o preenchimento do quadro por concurso e transformação do cargo de agente de segurança penitenciária e remeteu à lei os demais aspectos (art. 104, § 2º).",
p:["SENSO","Parece natural que a emenda que criou a Polícia Penal trouxesse suas atribuições. Ela, porém, remeteu à lei; o detalhamento está na LC 422/2019."]},

{d:"LEG",a:"LC 422/2019: atribuições",
e:"Entre as opções a seguir, assinale a única que NÃO corresponde a atribuição do policial penal de Pernambuco, conforme a Lei Complementar estadual nº 422/2019.",
o:["realizar policiamento ostensivo em vias públicas, sem relação com o sistema prisional.",
"facilitar as atividades de reinserção social e de tratamento penal.",
"realizar a contagem dos presos e a conferência periódica.",
"atuar em atividades de inteligência integrada.",
"realizar o recambiamento e a escolta de presos de outros estados."],
x:"A LC 422/2019 inclui contagem e conferência, inteligência integrada, recambiamento e escolta de presos de outros estados e facilitação de atividades de reinserção social. O policiamento ostensivo é da Polícia Militar (CE-PE, art. 105).",
p:["SENSO","“Facilitar a reinserção social” parece tarefa de assistente social, mas consta expressamente da lista de atribuições do policial penal."]},

{d:"LEG",a:"Lei 6.123/1968: processo disciplinar",
e:"Considere as afirmações a seguir acerca do processo disciplinar na Lei estadual nº 6.123/1968.\n\nI A sindicância é realizada por três servidores estáveis, no prazo de 60 dias.\nII O inquérito administrativo é conduzido por comissão de três servidores, com prazo de 90 dias.\nIII O prazo para a defesa escrita do indiciado é de 10 dias, ou de 20 dias, se houver dois ou mais indiciados.\n\nAssinale a opção correta.",
o:ITENS4, fixa:true, c:3, pi:4,
x:"II e III estão certos (arts. 220 e 232 da Lei 6.123/1968). I está errado: a sindicância estadual é feita por dois servidores, em 20 dias (art. 217). Três servidores estáveis e 60 dias são números do PAD da Lei 8.112/1990.",
p:["NUM","O item I usa os números do PAD federal (3 servidores, 60 dias) para a sindicância do estatuto estadual."]},

{d:"LEG",a:"Lei 6.123/1968: competência para punir",
e:"O diretor de uma unidade prisional de Pernambuco aplicou suspensão de 20 dias a um policial penal, com base apenas em sindicância. Considerando a Lei estadual nº 6.123/1968, aplicável subsidiariamente à LC nº 106/2007, essa penalidade",
o:["é irregular, pois a suspensão superior a 15 dias exige inquérito administrativo, e diretores de repartição só podem aplicar repreensão e suspensão de até 8 dias.",
"é regular, pois o diretor pode aplicar qualquer suspensão de até 30 dias.",
"é regular, pois a sindicância substitui o inquérito em qualquer hipótese.",
"é irregular apenas quanto à competência, sendo dispensável o inquérito.",
"é irregular, pois somente o governador pode aplicar suspensão."],
x:"Art. 208 da Lei 6.123/1968: diretores de repartição aplicam repreensão e suspensão até 8 dias; o governador aplica demissão e cassação; secretários, as demais. Art. 210: suspensão superior a 15 dias, destituição, demissão e cassação exigem inquérito administrativo.",
p:["NUM","30 dias é o limite máximo da suspensão no estatuto, não a competência do diretor, que vai só até 8 dias."]},

{d:"LEG",a:"Código Penitenciário de PE: recurso disciplinar",
e:"Após ser punido pelo Conselho Disciplinar por falta grave, um preso pretende recorrer. Conforme o Código Penitenciário do Estado de Pernambuco (Lei nº 15.755/2016), o recurso",
o:["deve ser interposto em 10 dias e não tem efeito suspensivo.",
"deve ser interposto em 10 dias e tem efeito suspensivo, impedindo o cumprimento da sanção até o julgamento.",
"deve ser interposto em 5 dias, diretamente ao juiz da execução.",
"é incabível contra sanções por falta grave.",
"deve ser interposto em 30 dias, com efeito suspensivo."],
x:"Art. 148 do Código Penitenciário de PE: recurso em 10 dias à comissão revisional, julgado em 30 dias, sem efeito suspensivo. Prazos do procedimento: notificação em 2 dias, instrução em 10, defesa em 2, decisão em 10.",
p:["SENSO","Recursos costumam suspender a decisão, mas aqui a lei afasta expressamente o efeito suspensivo, por razões de disciplina."]},

{d:"INF",a:"LGPD: âmbito de aplicação",
e:"Nos termos da Lei nº 13.709/2018 (LGPD), assinale a opção correta.",
o:["A LGPD não se aplica ao tratamento de dados pessoais realizado para fins exclusivos de segurança pública, defesa nacional, segurança do Estado ou atividades de investigação e repressão de infrações penais, que será regido por legislação específica.",
"A LGPD aplica-se integralmente a qualquer tratamento de dados realizado por órgãos de segurança pública, sem exceção.",
"A LGPD aplica-se apenas a empresas privadas, não alcançando o poder público.",
"O tratamento de dados pessoais pelo poder público depende sempre do consentimento do titular.",
"Dados anonimizados são considerados dados pessoais sensíveis."],
x:"Art. 4º, III, da LGPD exclui da lei o tratamento para fins exclusivos de segurança pública, defesa nacional, segurança do Estado e investigação e repressão penal, que deve ser regido por lei específica, observados os princípios gerais. A LGPD alcança o poder público (arts. 23 a 32), que pode tratar dados sem consentimento para executar políticas públicas e atribuições legais.",
p:["ALC","A LGPD é ampla, mas tem exceções expressas no art. 4º. Segurança pública e persecução penal com finalidade exclusiva estão fora."]},

{d:"INF",a:"Excel 365: referências",
e:"Em uma planilha do Excel 365, a célula C2 contém a fórmula =B2*$E$1. Se essa fórmula for copiada para a célula C3, o resultado em C3 será a fórmula",
o:["=B3*$E$1",
"=B3*$E$2",
"=B2*$E$1",
"=C3*$E$1",
"=B3*E2"],
x:"Na cópia, a referência relativa (B2) se ajusta à nova posição (B3), enquanto a absoluta ($E$1), travada pelos cifrões em linha e coluna, permanece inalterada.",
p:["CALC","O cifrão antes do número da linha ($1) impede que ela mude. Só a referência relativa B2 vira B3."]},

{d:"INF",a:"Navegadores: atalhos",
e:"No Google Chrome e no Microsoft Edge, para reabrir a última guia fechada acidentalmente, utiliza-se o atalho",
o:["Ctrl + Shift + T.",
"Ctrl + T.",
"Ctrl + H.",
"Ctrl + J.",
"Ctrl + Shift + N."],
x:"Ctrl + Shift + T reabre a última guia fechada. Ctrl + T abre nova guia; Ctrl + H, o histórico; Ctrl + J, os downloads; Ctrl + Shift + N, janela anônima no Chrome (no Edge, InPrivate é Ctrl + Shift + N também).",
p:["VIZ","Ctrl + T abre uma guia nova, em branco. Para recuperar a fechada, acrescenta-se o Shift."]},

{d:"INF",a:"Sítios de busca",
e:"Um servidor deseja pesquisar no Google páginas que contenham exatamente a expressão “policial penal”, apenas no domínio pe.gov.br. A pesquisa adequada é",
o:["\"policial penal\" site:pe.gov.br",
"policial penal + pe.gov.br",
"(policial penal) domain=pe.gov.br",
"policial-penal site=pe.gov.br",
"\"policial penal\" -pe.gov.br"],
x:"As aspas buscam a expressão exata, e o operador site: restringe os resultados ao domínio indicado. O sinal de menos (-) exclui termos ou sites dos resultados.",
p:["INV","O sinal de menos faz o oposto do pretendido: exclui o domínio pe.gov.br dos resultados."]},

/* ===================== P2 ===================== */
{d:"ADM",a:"Administração em sentido objetivo e subjetivo",
e:"Acerca dos sentidos da expressão administração pública, assinale a opção correta.",
o:["Em sentido objetivo, a administração pública corresponde à própria função administrativa, isto é, à atividade exercida pelo Estado; em sentido subjetivo, refere-se aos órgãos, entidades e agentes que a exercem.",
"Em sentido subjetivo, a administração pública corresponde à atividade administrativa; em sentido objetivo, aos órgãos e agentes.",
"Em sentido estrito, a administração pública abrange os órgãos governamentais que traçam as políticas públicas.",
"A administração pública em sentido subjetivo restringe-se ao Poder Executivo.",
"As empresas públicas não integram a administração pública em sentido subjetivo."],
x:"Objetivo (material/funcional): a atividade administrativa. Subjetivo (orgânico/formal): quem a exerce. Em sentido amplo, inclui os órgãos de governo (função política); em sentido estrito, apenas os que executam. Os Poderes Legislativo e Judiciário também exercem função administrativa atípica.",
p:["INV","Os dois sentidos são trocados. Dica: Subjetivo = Sujeitos; Objetivo = a atividade (o objeto)."]},

{d:"ADM",a:"Entidades paralelas (terceiro setor)",
e:"Acerca das entidades paralelas ao Estado, assinale a opção correta.",
o:["As organizações sociais, as organizações da sociedade civil de interesse público e os serviços sociais autônomos são pessoas jurídicas de direito privado que não integram a administração indireta.",
"Os serviços sociais autônomos, como o SESC e o SENAI, integram a administração indireta como autarquias.",
"As organizações sociais são criadas por lei específica como fundações públicas.",
"As OSCIPs são empresas estatais que exploram atividade econômica.",
"As entidades paralelas não podem receber recursos públicos."],
x:"Entidades paralelas (terceiro setor) colaboram com o Estado sem integrá-lo. São pessoas privadas sem fins lucrativos, que podem receber recursos públicos mediante contrato de gestão (OS), termo de parceria (OSCIP) ou contribuições (Sistema S), sujeitando-se a controle.",
p:["VIZ","O Sistema S recebe contribuições compulsórias e se submete a controle do TCU, o que o faz parecer autarquia. Mas não integra a administração indireta."]},

{d:"ADM",a:"Silêncio administrativo",
e:"No que diz respeito ao silêncio da administração pública, assinale a opção correta.",
o:["Em regra, o silêncio não produz efeitos de ato administrativo, salvo quando a lei lhe atribui expressamente consequência, como a aprovação ou a rejeição tácita.",
"O silêncio da administração sempre implica aprovação tácita do pedido.",
"O silêncio da administração sempre implica indeferimento do pedido.",
"O silêncio é ato administrativo discricionário, insuscetível de controle judicial.",
"Diante do silêncio, o Judiciário pode, em qualquer caso, praticar o ato no lugar da administração."],
x:"O silêncio é fato administrativo, e não ato, salvo quando a lei lhe atribui efeito. Diante da omissão ilegal, o interessado pode buscar o Judiciário, que, em regra, fixa prazo para a decisão (ou decide, se o ato for vinculado), mas não substitui o mérito do ato discricionário.",
p:["ABS","“Sempre” transforma em regra geral uma consequência que só existe quando a lei a prevê."]},

{d:"ADM",a:"Atos simples, complexos e compostos",
e:"Quanto à formação da vontade, os atos administrativos classificam-se em simples, complexos e compostos. Assinale a opção correta.",
o:["O ato complexo resulta da conjugação de vontades de órgãos diversos que se fundem para formar um único ato; o ato composto resulta da vontade de um órgão, dependente da verificação ou aprovação de outro, que é acessória.",
"O ato composto resulta da fusão de vontades autônomas de órgãos diferentes, formando um único ato; o complexo resulta da vontade de um órgão submetida a visto de outro.",
"O ato simples é sempre praticado por órgão singular, nunca por órgão colegiado.",
"O ato complexo é aquele que possui vários objetos simultaneamente.",
"Ato composto e ato complexo são expressões sinônimas."],
x:"Simples: uma única vontade (de órgão singular ou colegiado). Complexo: duas ou mais vontades autônomas que se fundem num só ato. Composto: um ato principal e outro acessório/instrumental (aprovação, visto, homologação).",
p:["INV","Complexo e composto são trocados. Lembre: no compLexo, as vontades se fundem (“L” de liga); no composto, há principal + acessório."]},

{d:"ADM",a:"Poder de polícia: delegação",
e:"Segundo a tese fixada pelo STF no Tema 532 da repercussão geral, é constitucional a delegação do poder de polícia, por meio de lei, a pessoas jurídicas de direito privado integrantes da administração pública indireta de capital social majoritariamente público que prestem exclusivamente serviço público de atuação própria do Estado e em regime não concorrencial,",
o:["no que se refere às fases de consentimento, fiscalização e sanção de polícia, mas não à ordem de polícia.",
"em todas as fases do ciclo de polícia, inclusive a ordem de polícia (legislação).",
"apenas no que se refere à fase de ordem de polícia.",
"desde que se trate de particulares sem vínculo com a administração.",
"exclusivamente quanto à aplicação de sanções, vedadas a fiscalização e o consentimento."],
x:"STF, RE 633.782 (Tema 532): admite a delegação, a estatais de direito privado com as características indicadas, das fases de consentimento, fiscalização e sanção. A ordem de polícia, por envolver a criação de limitações por lei, é indelegável.",
p:["ALC","A banca amplia a delegação a todo o ciclo. A ordem de polícia (a norma que restringe) continua privativa do Estado."]},

{d:"ADM",a:"Parceria público-privada (Lei 11.079/2004)",
e:"De acordo com a Lei nº 11.079/2004, é vedada a celebração de contrato de parceria público-privada",
o:["cujo valor seja inferior a R$ 10.000.000,00, cujo período de prestação do serviço seja inferior a 5 anos ou que tenha como objeto único o fornecimento de mão de obra, o fornecimento e instalação de equipamentos ou a execução de obra pública.",
"cujo valor seja inferior a R$ 20.000.000,00 ou cujo prazo seja superior a 20 anos.",
"para a construção e a gestão de estabelecimentos penais, em qualquer hipótese.",
"na modalidade administrativa, em que a administração é a usuária direta ou indireta do serviço.",
"com prazo superior a 5 anos, incluída a prorrogação."],
x:"Art. 2º, § 4º, da Lei 11.079/2004 (redação da Lei 13.529/2017): vedada PPP de valor inferior a R$ 10 milhões, com período inferior a 5 anos ou com objeto único de mão de obra, equipamentos ou obra. O prazo do contrato vai de 5 a 35 anos (art. 5º, I). Há PPPs prisionais no país, respeitada a indelegabilidade das funções de segurança e disciplina.",
p:["DESAT","O valor mínimo era de R$ 20 milhões até 2017, quando a Lei 13.529 o reduziu para R$ 10 milhões."]},

{d:"CON",a:"Mutação constitucional",
e:"A alteração do sentido de um dispositivo constitucional, sem modificação de seu texto, por meio da interpretação e da evolução dos costumes e da realidade social, denomina-se",
o:["mutação constitucional.",
"reforma constitucional por emenda.",
"revisão constitucional.",
"recepção.",
"desconstitucionalização."],
x:"Mutação é processo informal de alteração do sentido da Constituição, sem mudança do texto (ex.: releitura do papel do Senado no art. 52, X). Reforma e revisão são processos formais de alteração do texto. Recepção e desconstitucionalização tratam das normas anteriores à nova Constituição.",
p:["VIZ","Emenda e revisão alteram o texto. Na mutação, o texto fica igual e muda o sentido."]},

{d:"CON",a:"Poder Judiciário: súmula vinculante",
e:"Acerca da súmula vinculante, assinale a opção correta.",
o:["Pode ser aprovada pelo STF, de ofício ou por provocação, mediante decisão de dois terços dos seus membros, após reiteradas decisões sobre matéria constitucional, e o ato administrativo que a contrariar pode ser impugnado por reclamação.",
"Pode ser aprovada pela maioria absoluta dos membros do STF.",
"Vincula o Poder Legislativo no exercício da função legislativa.",
"Pode ser editada pelo STJ em matéria infraconstitucional.",
"Seus efeitos vinculantes alcançam apenas os órgãos do Poder Judiciário."],
x:"Art. 103-A da CF: aprovação por 2/3 dos membros do STF (8 ministros), com efeito vinculante para o Judiciário e a administração pública direta e indireta de todas as esferas. Cabe reclamação ao STF contra ato ou decisão que a contrarie (§ 3º). Não vincula o Legislativo na função de legislar.",
p:["NUM","Maioria absoluta (6) é o quórum para declarar inconstitucionalidade em plenário. A súmula vinculante exige 2/3 (8 ministros)."]},

{d:"CON",a:"Limitações ao poder de tributar",
e:"Acerca do princípio da anterioridade tributária, assinale a opção correta.",
o:["O imposto sobre a renda observa a anterioridade anual, mas não se submete à anterioridade nonagesimal.",
"O imposto sobre produtos industrializados (IPI) não se submete à anterioridade nonagesimal.",
"Todos os impostos se submetem simultaneamente à anterioridade anual e à nonagesimal.",
"O imposto sobre importação observa a anterioridade anual.",
"A anterioridade aplica-se apenas às taxas, não aos impostos."],
x:"Art. 150, § 1º, da CF: o IR é exceção apenas à noventena; o IPI é exceção apenas à anterioridade anual (observa a noventena); II, IE, IOF e o imposto extraordinário de guerra são exceção a ambas.",
p:["INV","IR e IPI são exceções opostas: o IR escapa da noventena; o IPI, da anterioridade anual."]},

{d:"CON",a:"EC 103/2019 (Reforma da Previdência)",
e:"Após a Emenda Constitucional nº 103/2019, a aposentadoria voluntária dos servidores públicos federais titulares de cargo efetivo, na regra geral permanente, exige idade mínima de",
o:["62 anos, se mulher, e 65 anos, se homem, observados o tempo de contribuição e os demais requisitos.",
"55 anos, se mulher, e 60 anos, se homem.",
"60 anos para ambos os sexos.",
"65 anos para ambos os sexos.",
"60 anos, se mulher, e 65 anos, se homem."],
x:"Art. 40, § 1º, III, da CF (redação da EC 103/2019): 62 anos (mulher) e 65 anos (homem), além de tempo de contribuição, de serviço público e no cargo fixados em lei. Os Estados disciplinam a idade de seus servidores nas próprias constituições e leis; as carreiras policiais têm regras específicas.",
p:["DESAT","55 e 60 anos eram as idades mínimas da regra anterior (EC 41/2003)."]},

{d:"CON",a:"Comunidades quilombolas",
e:"Segundo a Constituição Federal, aos remanescentes das comunidades dos quilombos que estejam ocupando suas terras",
o:["é reconhecida a propriedade definitiva, devendo o Estado emitir-lhes os títulos respectivos.",
"é assegurada a concessão de uso temporária, renovável a cada 10 anos.",
"é garantida a posse permanente, permanecendo a propriedade com a União.",
"é assegurado o usufruto exclusivo, como às terras indígenas.",
"é reconhecido o direito à indenização, mas não à titulação."],
x:"Art. 68 do ADCT: propriedade definitiva, com emissão de títulos pelo Estado. Já as terras tradicionalmente ocupadas pelos indígenas são bens da União (art. 20, XI), cabendo aos índios a posse permanente e o usufruto exclusivo (art. 231, § 2º).",
p:["VIZ","Posse permanente com propriedade da União é o regime das terras indígenas. Aos quilombolas, a CF assegura a propriedade."]},

{d:"CON",a:"Poder Executivo: responsabilidade do presidente",
e:"Quanto à responsabilização do presidente da República, assinale a opção correta.",
o:["Admitida a acusação por dois terços da Câmara dos Deputados, o presidente será julgado pelo STF nas infrações penais comuns e pelo Senado Federal nos crimes de responsabilidade.",
"O presidente é julgado pela Câmara dos Deputados nos crimes de responsabilidade, após autorização do Senado.",
"A admissão da acusação depende de maioria absoluta da Câmara dos Deputados.",
"Nos crimes comuns, o presidente é julgado pelo STJ.",
"Na vigência do mandato, o presidente pode ser responsabilizado por atos estranhos ao exercício de suas funções."],
x:"Art. 86 da CF: admitida a acusação por 2/3 da Câmara, julgamento pelo STF (crimes comuns) ou pelo Senado (responsabilidade). § 4º: na vigência do mandato, o presidente não pode ser responsabilizado por atos estranhos ao exercício de suas funções.",
p:["INV","Câmara admite; Senado julga (responsabilidade) e STF julga (comum). A banca troca os papéis das Casas."]},

{d:"PEN",a:"Teoria do crime: fato típico",
e:"Adotado o conceito analítico tripartido de crime, assinale a opção que apresenta corretamente os elementos do fato típico nos crimes materiais.",
o:["conduta, resultado naturalístico, nexo de causalidade e tipicidade.",
"conduta, ilicitude, culpabilidade e punibilidade.",
"tipicidade, ilicitude e culpabilidade.",
"conduta, imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa.",
"dolo, culpa, resultado e punibilidade."],
x:"No conceito tripartido, crime é fato típico, ilícito e culpável. O fato típico (nos crimes materiais) compõe-se de conduta, resultado naturalístico, nexo causal e tipicidade. A culpabilidade tem como elementos a imputabilidade, a potencial consciência da ilicitude e a exigibilidade de conduta diversa. Pela teoria finalista, dolo e culpa integram a conduta.",
p:["VIZ","A opção lista os substratos do crime (tipicidade, ilicitude e culpabilidade), e não os elementos do fato típico, que é só o primeiro deles."]},

{d:"PEN",a:"Crime consumado e tentado",
e:"No que se refere à tentativa, assinale a opção correta.",
o:["Não se pune a tentativa de contravenção penal.",
"Os crimes culposos admitem tentativa, com redução de um a dois terços.",
"A tentativa é punida com a pena do crime consumado, sem redução.",
"Os crimes omissivos próprios admitem tentativa em qualquer caso.",
"A tentativa só é punível nos crimes hediondos."],
x:"Art. 4º da Lei de Contravenções Penais: não é punível a tentativa de contravenção. Crimes culposos não admitem tentativa (não há vontade dirigida ao resultado). Art. 14, parágrafo único, do CP: a tentativa é punida com a pena do consumado reduzida de 1/3 a 2/3, salvo disposição em contrário.",
p:["SENSO","Parece que todo crime admite tentativa, mas no culposo não há intenção de chegar ao resultado, logo não há como “tentar”."]},

{d:"PEN",a:"Excesso punível",
e:"De acordo com o Código Penal, nas causas de exclusão da ilicitude,",
o:["o agente, em qualquer das hipóteses, responderá pelo excesso doloso ou culposo.",
"o excesso só é punível na legítima defesa.",
"o excesso culposo nunca é punível.",
"o excesso é sempre punido a título de dolo.",
"o estrito cumprimento do dever legal não admite excesso."],
x:"Art. 23, parágrafo único, do CP: o agente responde pelo excesso doloso ou culposo em qualquer das hipóteses (estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito).",
p:["ALC","O excesso é muito estudado na legítima defesa, o que leva a restringi-lo a ela. A regra vale para todas as excludentes."]},

{d:"PEN",a:"Feminicídio (Lei 14.994/2024)",
e:"Com as alterações promovidas pela Lei nº 14.994/2024 (pacote antifeminicídio), o feminicídio passou a",
o:["constituir crime autônomo, previsto no art. 121-A do Código Penal, com pena de reclusão de 20 a 40 anos.",
"constituir qualificadora do homicídio, com pena de reclusão de 12 a 30 anos.",
"constituir causa de aumento do homicídio simples.",
"ser julgado pelo juiz singular, e não pelo Tribunal do Júri.",
"ter como pena máxima 30 anos de reclusão."],
x:"A Lei 14.994/2024 retirou o feminicídio do rol de qualificadoras do art. 121 e o tipificou como crime autônomo (art. 121-A), com reclusão de 20 a 40 anos. Continua sendo crime doloso contra a vida, da competência do Júri, e hediondo.",
p:["DESAT","Até outubro de 2024, o feminicídio era qualificadora do homicídio (art. 121, § 2º, VI), com pena de 12 a 30 anos."]},

{d:"PEN",a:"Crimes contra a administração: resistência",
e:"Ao receber ordem legal de retorno à cela, um preso empurrou violentamente o policial penal para não ser conduzido. Essa conduta configura, em tese, o crime de",
o:["resistência.",
"desacato.",
"desobediência.",
"exercício arbitrário das próprias razões.",
"coação no curso do processo."],
x:"Art. 329 do CP: opor-se à execução de ato legal mediante violência ou ameaça a funcionário competente. Desobediência (art. 330) é o descumprimento sem violência; desacato (art. 331), a ofensa ao funcionário no exercício da função.",
p:["VIZ","Com violência ou ameaça para impedir o ato: resistência. Sem violência, só descumprindo: desobediência. Ofensa verbal: desacato."]},

{d:"PEN",a:"Fuga de preso: modalidade culposa",
e:"Por negligência, um policial penal deixou destrancado o cadeado de uma galeria, e dois presos fugiram. Não houve conluio. Essa conduta caracteriza, em tese,",
o:["facilitação culposa de fuga de pessoa presa (art. 351, § 4º, do CP).",
"promoção dolosa de fuga, com pena aumentada por ser o agente funcionário público.",
"evasão mediante violência contra a pessoa.",
"prevaricação, por ter deixado de praticar ato de ofício.",
"fato atípico, pois a fuga de presos não admite modalidade culposa."],
x:"Art. 351, § 4º, do CP: no caso de culpa do funcionário incumbido da custódia ou guarda, detenção de 3 meses a 1 ano, ou multa. A forma dolosa (caput e § 3º) tem pena maior. A evasão mediante violência (art. 352) é crime do próprio preso.",
p:["SENSO","Parece que só quem ajuda intencionalmente responde, mas o CP pune também o funcionário que, por culpa, facilita a fuga."]},

{d:"PPE",a:"Lei processual penal no tempo",
e:"Uma lei processual penal que alterou o procedimento de produção de determinada prova entrou em vigor durante a instrução de um processo. De acordo com o Código de Processo Penal,",
o:["a lei processual penal aplica-se desde logo, sem prejuízo da validade dos atos realizados sob a vigência da lei anterior.",
"a nova lei só se aplica aos processos iniciados após sua vigência.",
"a nova lei retroage para anular os atos praticados sob a lei anterior, se for mais benéfica.",
"aplica-se a lei vigente na data do fato, em qualquer hipótese.",
"a nova lei só se aplica se as partes concordarem."],
x:"Art. 2º do CPP: tempus regit actum — aplicação imediata, preservados os atos já praticados. Normas processuais puras não retroagem; normas híbridas (com conteúdo penal, como as que tratam de prescrição ou de representação) seguem a regra da retroatividade benéfica.",
p:["VIZ","A retroatividade benéfica é regra da lei penal. A lei processual pura aplica-se de imediato, sem retroagir."]},

{d:"PPE",a:"Assistente de acusação",
e:"Acerca do assistente de acusação no processo penal, assinale a opção correta.",
o:["O assistente será admitido enquanto não passar em julgado a sentença e receberá a causa no estado em que se achar.",
"O assistente pode intervir desde o inquérito policial.",
"O assistente pode ser admitido na ação penal privada.",
"O corréu no mesmo processo pode intervir como assistente do Ministério Público.",
"Da decisão que admitir ou não o assistente cabe recurso em sentido estrito."],
x:"Art. 269 do CPP: admissão enquanto não transitar em julgado a sentença. O assistente intervém na ação penal pública (art. 268), não no inquérito. O corréu não pode ser assistente (art. 270). Da decisão sobre a admissão não cabe recurso (art. 273), embora se admita mandado de segurança.",
p:["ALC","O assistente atua no processo, a partir do recebimento da denúncia, e não na fase de investigação."]},

{d:"PPE",a:"Reconhecimento de pessoas",
e:"Segundo o art. 226 do CPP e a jurisprudência atual do STJ, o reconhecimento de pessoas",
o:["deve observar o procedimento legal, como a descrição prévia da pessoa e sua colocação ao lado de outras semelhantes, e sua inobservância torna inválido o reconhecimento, que não pode servir de base para a condenação.",
"segue procedimento que constitui mera recomendação, de modo que sua inobservância não gera nenhuma consequência.",
"pode ser feito por fotografia, exclusivamente, sem necessidade de confirmação em juízo.",
"dispensa a descrição prévia da pessoa a ser reconhecida.",
"é sempre feito com a presença da pessoa a ser reconhecida diante do reconhecedor, sem anteparo."],
x:"Desde o HC 598.886 (2020), o STJ entende que o procedimento do art. 226 é garantia mínima do suspeito, e não mera recomendação. O reconhecimento irregular não serve de prova e não pode fundamentar condenação, ainda que confirmado em juízo; outras provas independentes podem ser utilizadas.",
p:["DESAT","Por muito tempo, os tribunais trataram o art. 226 como “mera recomendação”. O entendimento mudou em 2020."]},

{d:"PPE",a:"Uso de algemas (SV 11)",
e:"Conforme a Súmula Vinculante nº 11 do STF, o uso de algemas",
o:["só é lícito em casos de resistência e de fundado receio de fuga ou de perigo à integridade física própria ou alheia, por parte do preso ou de terceiros, justificada a excepcionalidade por escrito, sob pena de responsabilidade e de nulidade da prisão ou do ato processual.",
"é lícito em qualquer caso, bastando justificativa verbal da autoridade.",
"é obrigatório em toda escolta de preso, por razões de segurança.",
"é vedado em qualquer hipótese durante audiências judiciais.",
"depende de prévia autorização judicial em todos os casos."],
x:"A SV 11 exige que a excepcionalidade seja justificada por escrito, sob pena de responsabilidade disciplinar, civil e penal do agente e de nulidade da prisão ou do ato processual, sem prejuízo da responsabilidade civil do Estado.",
p:["EXC","A justificativa tem de ser escrita. A versão “verbal” é a pegadinha mais comum na súmula."]},

{d:"PPE",a:"Medidas cautelares diversas da prisão",
e:"Entre as medidas cautelares diversas da prisão previstas no art. 319 do CPP, inclui-se",
o:["o recolhimento domiciliar no período noturno e nos dias de folga, quando o investigado ou acusado tenha residência e trabalho fixos.",
"a prisão domiciliar da gestante, em substituição à prisão preventiva.",
"a prisão temporária por 5 dias.",
"a internação provisória do acusado imputável.",
"a condução coercitiva para interrogatório, como medida autônoma."],
x:"Art. 319 do CPP: comparecimento periódico em juízo, proibição de acesso a lugares, proibição de contato, proibição de ausentar-se da comarca, recolhimento domiciliar noturno e nos dias de folga, suspensão de função pública, internação provisória (inimputável ou semi-imputável), fiança e monitoração eletrônica. A prisão domiciliar (arts. 317, 318 e 318-A) substitui a preventiva.",
p:["VIZ","Recolhimento domiciliar noturno (cautelar diversa, art. 319) não se confunde com prisão domiciliar (forma de cumprir a preventiva, art. 318)."]},

{d:"PPE",a:"Crimes de responsabilidade dos funcionários públicos",
e:"No processo dos crimes afiançáveis de responsabilidade dos funcionários públicos (arts. 513 a 518 do CPP), estando a denúncia em devida forma, o juiz mandará notificar o acusado para responder por escrito no prazo de",
o:["15 dias, sendo essa defesa preliminar desnecessária, segundo o STJ, quando a ação penal estiver instruída por inquérito policial.",
"10 dias, sendo a defesa preliminar obrigatória em qualquer caso, sob pena de nulidade absoluta.",
"5 dias, apenas se o acusado estiver preso.",
"30 dias, prorrogáveis por igual período.",
"15 dias, aplicando-se também aos crimes inafiançáveis."],
x:"Art. 514 do CPP: resposta preliminar em 15 dias, antes do recebimento da denúncia, nos crimes funcionais afiançáveis. Súmula 330 do STJ: é desnecessária a resposta preliminar na ação penal instruída por inquérito policial.",
p:["NUM","10 dias é o prazo da resposta à acusação do procedimento comum (art. 396). A defesa preliminar dos crimes funcionais é de 15 dias."]},

{d:"LES",a:"Estatuto do Desarmamento: porte do policial penal",
e:"De acordo com o Estatuto do Desarmamento (Lei nº 10.826/2003), os integrantes do quadro efetivo de agentes e guardas prisionais",
o:["poderão portar arma de fogo de propriedade particular ou fornecida pela respectiva instituição, mesmo fora de serviço, desde que estejam submetidos a regime de dedicação exclusiva, sujeitos à formação funcional e subordinados a mecanismos de fiscalização e de controle interno.",
"só podem portar arma de fogo durante o serviço, vedado o porte fora dele em qualquer hipótese.",
"não têm direito a porte de arma de fogo, por não integrarem órgão policial.",
"podem portar arma de fogo apenas de uso restrito, fornecida pela União.",
"têm porte de arma de fogo condicionado a autorização judicial individual."],
x:"Art. 6º, VII, e § 1º-B, da Lei 10.826/2003 (incluído pela Lei 12.993/2014): porte mesmo fora de serviço, com arma particular ou institucional, desde que haja dedicação exclusiva, formação funcional e mecanismos de fiscalização e controle interno.",
p:["EXC","A regra geral restringe o porte de várias categorias ao serviço. Para os agentes prisionais, a lei admite expressamente o porte fora de serviço, com condições."]},

{d:"LES",a:"Lei de Drogas: causas de aumento",
e:"Segundo o art. 40 da Lei nº 11.343/2006, as penas do tráfico de drogas são aumentadas de",
o:["um sexto a dois terços, se a infração tiver sido cometida nas dependências ou imediações de estabelecimentos prisionais.",
"um terço até a metade, se a infração tiver sido cometida nas dependências ou imediações de estabelecimentos prisionais.",
"metade, se o agente for reincidente.",
"um sexto a dois terços, apenas se a droga for destinada a presos.",
"dois terços, se a infração envolver qualquer quantidade de cocaína."],
x:"Art. 40, III, da Lei 11.343/2006: aumento de 1/6 a 2/3 se a infração for cometida nas dependências ou imediações de estabelecimentos prisionais, de ensino, hospitalares, entre outros. A lei não exige que a droga seja destinada aos frequentadores do local.",
p:["NUM","As frações de aumento variam de lei para lei. No art. 40 da Lei de Drogas, o aumento é de 1/6 a 2/3, e não de 1/3 até a metade."]},

{d:"LES",a:"Tortura: omissão",
e:"O chefe de plantão de uma unidade prisional presenciou policiais penais submeterem um preso a intenso sofrimento físico como forma de castigo e nada fez para impedir, embora pudesse. Conforme a Lei nº 9.455/1997, o chefe de plantão",
o:["responde por crime de tortura na forma omissiva, punido com detenção de 1 a 4 anos.",
"responde pela mesma pena dos executores, reclusão de 2 a 8 anos.",
"não comete crime, pois não praticou atos de violência.",
"responde apenas por prevaricação.",
"responde por condescendência criminosa, exclusivamente."],
x:"Art. 1º, § 2º, da Lei 9.455/1997: quem se omite em face dessas condutas, quando tinha o dever de evitá-las ou apurá-las, incorre na pena de detenção de 1 a 4 anos. A tortura-castigo (art. 1º, II) é punida com reclusão de 2 a 8 anos.",
p:["ALC","Pela regra geral da omissão imprópria, o garante responderia como autor. A Lei de Tortura, porém, criou pena própria e menor para o omisso."]},

{d:"LES",a:"Lei Maria da Penha: descumprimento de medida protetiva",
e:"Após a Lei nº 14.994/2024, o crime de descumprimento de decisão judicial que defere medidas protetivas de urgência (art. 24-A da Lei nº 11.340/2006) é punido com",
o:["reclusão de 2 a 5 anos e multa, e, na hipótese de prisão em flagrante, apenas a autoridade judicial poderá conceder fiança.",
"detenção de 3 meses a 2 anos, admitida fiança pela autoridade policial.",
"detenção de 1 a 3 anos, com aplicação da Lei nº 9.099/1995.",
"multa, apenas, por se tratar de infração de menor potencial ofensivo.",
"reclusão de 2 a 5 anos, admitida transação penal."],
x:"A Lei 14.994/2024 elevou a pena do art. 24-A para reclusão de 2 a 5 anos e multa. O § 2º reserva ao juiz a concessão de fiança no flagrante. O crime se configura independentemente da competência civil ou criminal do juiz que deferiu as medidas.",
p:["DESAT","A pena original (Lei 13.641/2018) era de detenção de 3 meses a 2 anos."]},

{d:"LES",a:"Colaboração premiada (Lei 12.850/2013)",
e:"Acerca da colaboração premiada na Lei nº 12.850/2013, assinale a opção correta.",
o:["O juiz não participará das negociações realizadas entre as partes para a formalização do acordo, e nenhuma sentença condenatória será proferida com fundamento apenas nas declarações do colaborador.",
"O juiz deve participar das negociações para garantir a legalidade do acordo.",
"A sentença condenatória pode basear-se exclusivamente nas declarações do colaborador.",
"O acordo de colaboração só pode ser celebrado após a sentença.",
"O colaborador pode exercer o direito ao silêncio durante os depoimentos objeto do acordo."],
x:"Art. 4º, § 6º: o juiz não participa das negociações. § 16: não se decreta medida cautelar, nem se recebe denúncia, nem se profere sentença com fundamento apenas nas declarações do colaborador. § 14: o colaborador renuncia ao direito ao silêncio nos depoimentos. O acordo pode ocorrer antes, durante ou após o processo.",
p:["SENSO","Parece prudente o juiz acompanhar a negociação, mas a lei o afasta para preservar sua imparcialidade; ele só homologa."]},

{d:"LES",a:"Crimes eleitorais: prisão de eleitor",
e:"Segundo o Código Eleitoral (Lei nº 4.737/1965), nenhuma autoridade poderá prender ou deter qualquer eleitor",
o:["desde 5 dias antes e até 48 horas depois do encerramento da eleição, salvo em flagrante delito, em virtude de sentença criminal condenatória por crime inafiançável ou por desrespeito a salvo-conduto.",
"desde 15 dias antes e até 48 horas depois da eleição, salvo em flagrante delito.",
"durante todo o período de propaganda eleitoral, salvo por ordem judicial.",
"apenas no dia da eleição, sem exceções.",
"desde 5 dias antes até 5 dias depois da eleição, inclusive em flagrante."],
x:"Art. 236 do Código Eleitoral: 5 dias antes até 48 horas depois do encerramento da eleição, com as exceções do flagrante, da sentença condenatória por crime inafiançável e do desrespeito a salvo-conduto. Membros de mesas e fiscais têm a mesma proteção durante o exercício de suas funções, e os candidatos, desde 15 dias antes da eleição (§ 1º).",
p:["NUM","15 dias é o prazo de proteção dos candidatos. Para o eleitor, são 5 dias antes."]},

{d:"EXE",a:"LEP: órgãos da execução penal",
e:"Conforme o art. 61 da Lei de Execução Penal, são órgãos da execução penal, entre outros,",
o:["o Conselho da Comunidade e a Defensoria Pública.",
"a Polícia Civil e o Conselho Tutelar.",
"o Tribunal do Júri e o Ministério da Justiça.",
"a Ordem dos Advogados do Brasil e a Polícia Militar.",
"o Conselho Nacional de Justiça e as Secretarias de Segurança Pública."],
x:"Art. 61 da LEP: Conselho Nacional de Política Criminal e Penitenciária, Juízo da Execução, Ministério Público, Conselho Penitenciário, Departamentos Penitenciários, Patronato, Conselho da Comunidade e Defensoria Pública (incluída pela Lei 12.313/2010).",
p:["SENSO","A Polícia Civil atua perto do sistema prisional, o que a torna plausível. Mas o rol do art. 61 não a inclui."]},

{d:"EXE",a:"Competência: juiz da execução × diretor",
e:"Considerando a LEP, compete ao diretor do estabelecimento, e não ao juiz da execução,",
o:["conceder permissão de saída ao preso em caso de falecimento de familiar.",
"decidir sobre a progressão de regime.",
"autorizar saídas temporárias.",
"declarar a remição de pena.",
"decidir sobre a inclusão do preso no regime disciplinar diferenciado."],
x:"Art. 120, parágrafo único, da LEP: a permissão de saída é concedida pelo diretor do estabelecimento. Progressão, saída temporária, remição e RDD são da competência do juiz da execução (arts. 54, 66 e 123).",
p:["COMP","Permissão de saída (diretor, com escolta, por falecimento ou doença) e saída temporária (juiz, sem vigilância direta, para estudo) são trocadas pela banca."]},

{d:"EXE",a:"Regressão e progressão por salto",
e:"Considere as afirmações a seguir.\n\nI É admitida a regressão de regime por salto, do regime aberto diretamente para o fechado.\nII É admitida a progressão de regime por salto, do fechado diretamente para o aberto.\nIII A regressão por falta grave exige a prévia oitiva do condenado.\n\nAssinale a opção correta.",
o:["Apenas o item I está certo.","Apenas o item II está certo.","Apenas os itens I e III estão certos.","Apenas os itens II e III estão certos.","Todos os itens estão certos."], fixa:true, c:2, pi:4,
x:"I certo: o art. 118 da LEP admite transferência “para qualquer dos regimes mais rigorosos”. II errado: a Súmula 491 do STJ veda a progressão per saltum. III certo: na regressão por falta grave ou crime doloso, o condenado deve ser ouvido previamente (art. 118, § 2º).",
p:["INV","Regressão por salto é permitida; progressão por salto é vedada. Quem acha as duas iguais marca “todos certos”."]},

{d:"EXE",a:"Exame criminológico (Lei 14.843/2024)",
e:"Para a progressão de regime, após a Lei nº 14.843/2024, a LEP passou a exigir, além do cumprimento da fração legal da pena,",
o:["boa conduta carcerária, comprovada pelo diretor do estabelecimento, e os resultados do exame criminológico.",
"apenas boa conduta carcerária, sendo vedada a exigência de exame criminológico.",
"exame criminológico somente para crimes hediondos.",
"parecer favorável do Conselho Penitenciário.",
"reparação integral do dano em qualquer caso."],
x:"Art. 112, § 1º, da LEP (redação da Lei 14.843/2024): o condenado só terá direito à progressão se ostentar boa conduta carcerária, comprovada pelo diretor, e pelos resultados do exame criminológico, respeitadas as normas que vedam a progressão.",
p:["DESAT","Desde a Lei 10.792/2003, o exame criminológico deixara de ser obrigatório (Súmula 439 do STJ: admitido se motivado). Em 2024, voltou a ser exigido."]},

{d:"EXE",a:"Sistema Penitenciário Federal: competência",
e:"Incluído um preso em estabelecimento penal federal de segurança máxima, conforme a Lei nº 11.671/2008, a execução penal",
o:["será de competência do juízo federal da seção ou subseção judiciária em que estiver localizado o estabelecimento.",
"permanece com o juízo estadual de origem, que fiscaliza o cumprimento por carta precatória.",
"passa ao STJ, em razão da natureza federal do estabelecimento.",
"passa ao juízo da capital do Estado de origem do preso.",
"fica a cargo do diretor do presídio federal, sem controle judicial."],
x:"Art. 2º da Lei 11.671/2008: a atividade jurisdicional de execução penal nos estabelecimentos federais é desenvolvida pelo juízo federal da seção ou subseção judiciária em que estiver situado o estabelecimento.",
p:["COMP","O juízo de origem pede a transferência e pode pedir a renovação, mas, enquanto o preso estiver no federal, a execução é do juízo federal local."]},

{d:"EXE",a:"Monitoração eletrônica",
e:"Durante saída temporária fiscalizada por monitoração eletrônica, um condenado danificou deliberadamente a tornozeleira. Conforme a LEP, a violação comprovada dos deveres do monitorado poderá acarretar, a critério do juiz da execução, ouvidos o MP e a defesa,",
o:["a regressão do regime, a revogação da autorização de saída temporária ou da prisão domiciliar, ou advertência por escrito, entre outras medidas.",
"apenas advertência verbal, por se tratar de infração leve.",
"a conversão automática da pena em multa.",
"a inclusão imediata no RDD, por ato do diretor.",
"nenhuma consequência, se o condenado retornar no prazo."],
x:"Art. 146-C, parágrafo único, da LEP: a violação comprovada dos deveres pode acarretar regressão, revogação da saída temporária, revogação da prisão domiciliar, advertência por escrito, entre outras, a critério do juiz. Em PE, danificar o equipamento é falta grave pelo Código Penitenciário.",
p:["SENSO","Parece infração menor, mas o rompimento da tornozeleira pode levar à regressão de regime."]},

{d:"DH",a:"Terminologia: direitos humanos e fundamentais",
e:"Acerca da terminologia dos direitos humanos, assinale a opção correta.",
o:["A expressão “direitos fundamentais” costuma designar os direitos reconhecidos e positivados na Constituição de um Estado, ao passo que “direitos humanos” se refere aos previstos em documentos de direito internacional.",
"“Direitos humanos” designa os direitos positivados na Constituição, e “direitos fundamentais”, os previstos em tratados.",
"Direitos humanos e direitos do homem são expressões que se referem exclusivamente aos direitos naturais, sem previsão normativa.",
"Os direitos fundamentais não podem ser objeto de tratados internacionais.",
"A distinção terminológica impede que um mesmo direito seja, ao mesmo tempo, humano e fundamental."],
x:"Na doutrina majoritária: direitos humanos (plano internacional), direitos fundamentais (positivados na Constituição) e direitos do homem (concepção jusnaturalista). Um mesmo direito, como a vedação da tortura, pode ser humano e fundamental.",
p:["INV","As expressões são trocadas: “fundamentais” é o termo ligado à Constituição; “humanos”, ao plano internacional."]},

{d:"DH",a:"Conselho Nacional de Política Criminal e Penitenciária",
e:"Conforme os arts. 62 a 64 da LEP, o Conselho Nacional de Política Criminal e Penitenciária (CNPCP)",
o:["tem sede na capital da República, é subordinado ao Ministério da Justiça e é integrado por 13 membros designados por ato do Ministério da Justiça, com mandato de 2 anos, renovado 1/3 em cada ano.",
"é composto por membros eleitos pelo Congresso Nacional, com mandato de 4 anos.",
"é órgão do Poder Judiciário, vinculado ao CNJ.",
"tem como atribuição exclusiva a concessão de indulto.",
"é composto apenas por magistrados e membros do Ministério Público."],
x:"Arts. 62 e 63 da LEP: sede na capital, subordinação ao Ministério da Justiça, 13 membros designados pelo Ministério da Justiça entre professores e profissionais da área do direito penal, processual penal, penitenciário e ciências correlatas, além de representantes da comunidade e dos ministérios da área social; mandato de 2 anos, renovado 1/3 a cada ano. O art. 64 lista suas atribuições (propor diretrizes, inspecionar, avaliar o sistema etc.). O indulto é do presidente da República.",
p:["COMP","O CNPCP é órgão do Executivo federal. O indulto é ato do presidente; o CNPCP apenas pode opinar e propor diretrizes."]},

{d:"DH",a:"Regras de Mandela: instrumentos de coação",
e:"De acordo com as Regras de Mandela, assinale a opção correta acerca dos instrumentos de coação.",
o:["É proibido o uso de correntes, ferros ou outros instrumentos de coação inerentemente degradantes ou dolorosos.",
"O uso de algemas é proibido em qualquer situação.",
"Os instrumentos de coação podem ser usados como forma de sanção disciplinar.",
"Os instrumentos de coação podem permanecer em uso por tempo indeterminado, a critério do diretor.",
"O uso de algemas em mulheres durante o parto é admitido quando a unidade estiver superlotada."],
x:"Regra 47: proíbe correntes, ferros e instrumentos inerentemente degradantes ou dolorosos; outros instrumentos só quando autorizados por lei e em hipóteses como prevenção de fuga durante transferência ou para impedir dano. Regra 48: uso pelo tempo estritamente necessário e nunca como sanção; vedado em mulheres em trabalho de parto, durante e logo após o parto.",
p:["ABS","As Regras não proíbem algemas em qualquer situação; admitem seu uso excepcional e necessário. O que proíbem são correntes e ferros."]},

{d:"DH",a:"Pacto de São José: garantias",
e:"De acordo com a Convenção Americana sobre Direitos Humanos, assinale a opção correta.",
o:["Toda pessoa acusada de delito tem direito de recorrer da sentença para juiz ou tribunal superior.",
"A pena de morte pode ser aplicada a menores de 18 anos nos crimes mais graves.",
"A pena de morte pode ser estendida a delitos aos quais não se aplicava quando da ratificação.",
"As penas podem passar da pessoa do delinquente quando houver dano ao erário.",
"O direito à vida é protegido apenas a partir do nascimento."],
x:"Art. 8.2.h: direito de recorrer da sentença (duplo grau). Art. 4: não se aplica pena de morte a menores de 18 ou maiores de 70 anos, nem a mulheres grávidas; não se estende a delitos aos quais não se aplicava; o direito à vida é protegido, em geral, desde a concepção. Art. 5.3: a pena não pode passar da pessoa do delinquente.",
p:["SENSO","A ideia de punição mais severa para crimes graves soa razoável, mas o Pacto proíbe expressamente a pena de morte para menores de 18 anos."]}
]
});
